using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class GiorgioBassani
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Tutto è perfetto, e la tua mano maestra si sente dovunque.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Perché dell'avvenire cui si assume esitante ancora la mia vita verrà un riso?", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Tutti viviamo come nemici assediati dentro un mastio di ferro.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Io vi dico: curviamoci sui nostri passi, sulle nostre lanterne da minatori.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "«Chissà», tenti; «e se questo nostro vivere è un sogno?", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "M'avessi da bambino serbato alla tua Legge. Stato sarei del gregge dei morti a capo chino.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "«Vide cor meum»: Tu, chiami? Oh il cuore, il cuore, niente altro di me ti specchia dal profondo.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Soltanto l'insistenza del padre aveva potuto indurre Girolamo Camaioli a seguire i funerali dello zio Celio.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "La mamma, sorridendo come solo sanno sorridere i morti nella memoria, pieni di compatimento e di indulgenza [...], gli aveva posato dolcemente una mano sulla bocca.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "L'amore, in fondo, ha il suo migliore alimento nei contrasti, nei sotterfugi...", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Erano stati due schiaffi che, dopo qualche momento di muto stupore, avevano risposto fulminei alle domande insistenti, se pure cortesi, di Lionello Scocca.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Giorno o notte che sia, estate o inverno; che piova o no: la gente se deve passare per di lì, è difficile che non preferisca infilarsi sotto il basso portichetto dove si annidano in penombra i locali contigui del Caffè della Borsa e dell'antica farmacia Barilari, anziché tenersi dalla parte opposta, al marciapiede che segue in linea retta la Fossa del Castello.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Il professor Bianchi, d'italiano, aveva cominciato le lezioni declamando una canzone di Dante, e un verso, di questa, mi aveva straordinariamente colpito.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "«L'essilio che m'è dato a onor mi tegno». Poteva essere la mia divisa – pensavo –, il mio motto.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Come due giovani sposi, unitisi non per scelta spontanea ma per volontà superiore, stavamo assieme ben consapevoli, entrambi, del significato sociale e della mondana importanza della nostra unione.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Non c'è nulla più dell'onesta pretesa di mantenere distinto nella propria vita ciò che è pubblico da ciò che è privato, che ecciti l'interesse indiscreto delle piccole società perbene.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "«La guardi», diceva intanto Fadigati, indicandomela [la cagna]. «Forse bisognerebbe essere così, sapere accettare la propria natura.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Nell'uomo c'è molto della bestia, eppure può, l'uomo, arrendersi? Ammettere di essere una bestia, e soltanto una bestia?»", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "«Che cosa dovrei fare?», lo interruppi con impeto. «Accettare di essere quello che sono? O meglio adattarmi ad essere quello che gli altri vogliono che io sia?»", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "La gioia di mio padre – pensavo – era quella dello scolaretto ingiustamente espulso, il quale, richiamato indietro per ordine del maestro dal corridoio deserto dove rimase per un poco di tempo in esilio, si trovi, a un tratto, contro ogni sua aspettativa, riammesso in aula fra i cari compagni: non soltanto assolto, ma riconosciuto innocente e riabilitato in pieno.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Respirai profondamente. E adesso capivo, sì, già prima che cominciassi a leggere il mezzo colonnino sotto il titolo, il quale non parlava affatto di suicidio, s'intende, ma, secondo lo stile dei tempi, soltanto di disgrazia.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "«Si capisce», rispose. «I morti da poco sono più vicini a noi, e appunto per questo gli vogliamo più bene.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Lì, tuttavia, nel breve recinto sacro ai morti familiari...almeno lì [...] nulla sarebbe mai cambiato.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Pregava. Pregava per noi poverini, certo, inetti all'algebra quasi tutti; ma anche forse per affrettare la conversione al cattolicesimo dei signori israeliti [...].", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "In fase di espansione imperialistica il capitalismo non può che mostrarsi intollerante nei confronti di tutte le minoranze nazionali, e degli ebrei, in particolare, che sono la minoranza per antonomasia.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "La verità è che a furia di far collezioni, di cose, di piante, di tutto, si finisce a poco a poco col voler farle anche con le persone.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Anche le cose muoiono, caro mio. E dunque, se anche loro devono morire, tant'è, meglio lasciarle andare.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Una delle forme più odiose di antisemitismo era appunto questa: lamentare che gli ebrei non fossero abbastanza ''come'' gli altri, e poi, viceversa, constatata la loro pressoché totale assimilazione all'ambiente circostante, lamentare che fossero tali e quali come gli altri, nemmeno un poco diversi dalla media comune.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Mi aggrappavo alla scrivanietta che il professore Ermanno dal gennaio scorso aveva fatto collocare per me sotto la finestra di mezzo del salone del biliardo, come se, così facendo, mi fosse dato di arrestare l'inarrestabile progresso del tempo.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Qui sedevamo noi, i vivi [...] tristi e pensierosi come dei morti.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Anche se li sapevo [...] disadatti a valutare la reale portata dell'oggi li vedevo, avvolti nella memoria.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Io ero rimasto qui, e per me, che ero rimasto...per me in realtà non c'era speranza, non c'era nessuna speranza.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Ancora qualche secondo, e avrei udito la sua voce, il suo «ciao». «Ciao» disse Micòl, ferma sulla soglia. «Che bravo, a venire.»", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Avevo previsto tutto con molta esattezza: tutto, tranne che l'avrei baciata.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "«E per quale motivo, poi?» chiesi, tornando col libro in mano.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "«Perché non gli andava di far altro che lo scrivano. Lo scrivano e basta.»", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "«Però scusa» obbiettai. «immagino che Spencer Tracy gli passasse un regolare stipendio.»", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Discutemmo abbastanza a lungo sul povero Bartleby e su Spencer Tracy. Lei mi rimproverava di non capire, di essere «''un''» banale, il solito inveterato conformista.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "[...] ebbi il senso preciso che stavo perdendola, che l'avevo perduta.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Eh, sì, tagliare la corda è facile: ma a cosa porta, quasi sempre, specie in materia di «situazioni morbide»?", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Domandai a Micòl perché le sembrasse tanto impossibile che lui e lei potessero fare l'amore.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Per infinite ragioni – rispose –: la prima delle quali era che a pensar di far l'amore con me le riusciva altrettanto imbarazzante che se avesse pensato di farlo con il fratello, toh, con Alberto.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Io… io le stavo ''di fianco'', capivo?, non già ''di fronte'': mentre l'amore – così, almeno, se lo immaginava lei – era roba per gente decisa a sopraffarsi a vicenda: uno sport crudele, feroce, ben più crudele e feroce del tennis!, da praticarsi senza esclusione di colpi e senza mai scomodare, per mitigarlo, bontà d'animo e onestà di propositi.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "[...] l'amore (così almeno se lo figurava lei) era roba per gente decisa a sopraffarsi a vicenda, uno sport crudele, feroce, ben più crudele e feroce del tennis!, da praticarsi senza esclusioni di colpi e senza mai scomodare, per mitigarlo, bontà d'animo ed onestà di propositi.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "[...] più del presente contava il passato, più del possesso il ricordarsene. Di fronte alla memoria, ogni possesso non può apparire che delusivo, banale, insufficiente.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Era il 'nostro' vizio questo: d'andare avanti con le teste sempre voltate all'indietro.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Non gli restava che comportarsi come Don Abbondio. Inchinarsi, e mormorare:'Disposto sempre all'obbedienza'.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Nella vita, se uno vuol capire, capire sul serio come stanno le cose di questo mondo, deve morire almeno una volta.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Mi sentivo, ed ero, una specie di strano fantasma trascorrente: pieno di vita e di morte insieme; di passione e di distaccata pietà.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "«{{NDR|Micòl}} Sono anche io come tutte le altre: bugiarda, traditora, ''infedele''… Non molto diversa da un'Adriana Trentini qualsiasi, in fondo».", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Aveva detto «infedele» spiccando le sillabe, con una specie di amaro orgoglio.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Tuttavia era un fatto: lei ''aveva sempre letto nei miei occhi tanto «idealismo» da sentirsi in qualche modo forzata ad apparire migliore di quanto non fosse in realtà.''", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Ma Micòl non discese, per questo, dal piedistallo di purezza e di superiorità morale su cui, da quando ero partito per l'esilio, l'avevo collocata.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Io, per me, mi consideravo fortunato di essere stato riammesso ad ammirarne ogni tanto l'immagine lontana, bella di dentro non meno che di fuori.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Io, al contrario, sostenevo che l'amore giustifica e santifica tutto, perfino la pederastia; di più: che l'amore, quando è puro, cioè totalmente disinteressato, è sempre anormale, asociale, eccetera: proprio come l'arte – avevo aggiunto –, che quando è pura, dunque inutile, dispiace a tutti i preti di tutte le religioni, compresa quella socialista.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "La paura, anche in arte, è sempre stata una pessima consigliera.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Che cosa c'è stato, fra loro due? Niente? Chissà.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "E siccome queste, lo so, non erano che parole, le solite parole ingannevoli e disperate che soltanto un vero bacio avrebbe potuto impedirle di proferire: di esse, appunto, e non di altre, sia suggellato qui quel poco che il cuore ha saputo ricordare.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Eppure no, ''non'' doveva cedere, rassegnarsi.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Ripercorrere in senso contrario la strada piena di curve che aveva percorso poco fa, ripassare sotto Pomposa, riattraversare Codigoro o quanto meno girarle attorno, e infine, verso le undici, scorgere profilarsi di lontano le quattro torri del castello Estense: tutto questo non sarebbe valso che a ripiombarlo, non ne aveva il più piccolo dubbio, in fondo a quel medesimo cupo pozzo di tristezza accidiosa da cui a un certo punto aveva creduto di essere emerso definitivamente.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Veniva avanti l'airone, adesso, sempre più avanti, mostrandoglisi con straordinaria, quasi insopportabile evidenza.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Sulla testina perfettamente liscia inalberava per di dietro qualcosa di esile: una specie di filo, di antenna, chi lo sa.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "E lui, col cuore che frattanto aveva cominciato a battergli forte contro l'osso dello sterno, stava appunto chiedendosi che cosa diamine potesse essere quello strano affare, e stringeva le palpebre per cercare di vedere meglio, quando, all'improvviso, nella vasta aria soleggiata e ventosa, udì echeggiare il solito doppio sparo.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Come erano tranquilli e beati gli altri, tutti gli altri! – tornava a ripetersi, riabbassata la testa sul piatto –. Come erano bravi a godersi la vita!", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "La sua pasta si vede era diversa, inguaribilmente diversa, da quella della gente normale che una volta mangiato e bevuto non bada che a digerire.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Di là dal vetro il silenzio, l'immobilità assoluta, la pace.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Guardava ad una ad una le bestie imbalsamate, magnifiche tutte nella loro morte, più vive che se fossero vive.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Vivi ad ogni modo anche gli uccelli di una vita che non correva più nessun rischio di deteriorarsi, tirati a lucido, ma soprattutto diventati di gran lunga più belli i quanto respiravano e il sangue correva veloce nelle loro vene, lui solo, forse – pensava – era in grado di ''capirla'' davvero la perfezione di quella loro bellezza finale e non deperibile, di apprezzarla sino in fondo.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Si sentiva incredibilmente ricco, generoso, disposto a dare: in preda a una specie di ebbrezza.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Sarebbe bastato che, per questo, si fosse indotto a pensare di sopravvivere un solo giorno di più, perché la felicità che da un'ora portava chiusa dentro se stesso come un tesoro si dissolvesse di colpo, e perché tornasse a provare anche nei confronti di sua figlia, rimasta là, a fissarlo al disopra dell'orlo del cucchiaio coi suoi begli occhi di un blu cupo, selvatico, il consueto, amaro senso di estraneità, quasi di repulsione, che gli aveva sempre impedito di considerarla sua, di volerle bene.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Ecco, dunque – si diceva –: soltanto a patto di morire poteva volerle bene, alla Rory!", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Dal che si vede che, dal fondo della miseria, gli agi e i piaceri della vita, in sé vani e caduchi, possono acquistare un valore spirituale vero e proprio.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Cara Jenny, per disegnare bene, bisogna essere molto cattivi, ricordatelo.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Bisogna smontare il mondo, per ricostruirlo poi pezzo a pezzo, con infinita pazienza.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "La poesia è delle anime vergini, degli angeli, di chi crede.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Ma ad ogni modo, per essere poeti bisogna tornare a una necessaria ''condizione d'ingenuità''.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Un incubo doloroso e confuso, ecco cosa sono i nostri giorni.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "In Hitler il popolo tedesco ha trovato riassunti, al di sopra di ogni schema tradizionale di divisioni classistiche, alcuni dei motivi essenziali da sempre ritornanti a definire il proprio carattere, la fisionomia del proprio ethos: il gusto della violenza, il misticismo «romantico», la fanatica dedizione a un ordine meccanico, disumano.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Hitler sapeva trascinare il grande industriale con l'esca dell'interesse e col ricorso al mito prediletto della supremazia tedesca nel mondo; affascinava il piccolo borghese col suo estetismo pompier, con la sua oratoria accesa e volgare, pronta sempre ad offrire, di ogni problema, la soluzione più semplicistica; piaceva all'intellettuale decadente, permeato di femmineo postnicianesimo (l'intelligencija tedesca già nel 1914 era in stato fallimentare come nessun'altra in Europa), per la sua ostentata energia virile, per il suo dichiarato disprezzo di ogni indugio morale o sentimentale, per quel suo rozzo materialismo demagogico che, nonostante tutto, pretendeva considerazione «spirituale».", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Conquistava infine anche l'operaio, facendo leva non soltanto sul suo sciovinismo non perfettamente esorcizzato, ma porgendogli, anche, delle sue rivendicazioni sociali, un'attuazione più concretamente immediata, meno utopica e intellettualistica di quanto non gliela prospettasse il programma della rivoluzione proletaria: e fosse pure nei limiti di una umiliante, paternalistica nota di concessioni padronali.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Il nazismo non è certo la realizzazione di un genio. Hitler è effettivamente uno dei tanti [...].", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Parlare di tirannide perciò non persuade. Esiste una tecnica della tirannide, esposta in classiche trattazioni.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Ma il nazionalsocialismo al potere non ne tiene conto per nulla, e in questo sì che è rivoluzionario.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Assolutista, il nazismo raggiunge la popolarità proprio in ragione del suo prepotere.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Il nazionalsocialismo, al contrario, non concede nessuna rivincita, sia pure formale, alle avanguardie dello Spirito.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Il suo cinismo, la sua crudeltà, la sua perfidia, trovano dall'inizio tutta una orgogliosa cultura preparata a giustificarli, a farseli propri.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "La tirannide non presenta più il viso odioso e meschino del regime di polizia, non adopera più di soppiatto, tra impaurita e feroce, i vecchi mezzucci della sobillazione e della calunnia, ma si accampa, fanatica e violenta, con la sicurezza, l'intransigenza esclusiva di una religione messianica.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Sentirsi puri, non contaminati. Il popolo tedesco ha sempre reagito alle proprie crisi con un disperato, irrazionale desiderio di purezza: e la rivolta luterana – a un livello umano e ideale ben diverso, d'accordo – rappresenta forse il primo, imponente documento storico di questo impulso innato.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Sorto dopo Versaglia, il nazionalsocialismo non si è tanto imposto con la violenza alle masse, quanto piuttosto le ha trovate già pronte ad accoglierlo e ad acclamarlo.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "La disinvoltura linguistica del dialogo manzoniano cos'altro è se non il segno, la spia, di una religione indifferente alla realtà, alla realtà così com'è intesa dai romanzieri realisti?", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "In un mondo come il nostro, volto con sempre più consapevole determinazione, ad est e ad ovest, a nord e a sud, alla ricerca e all'impiego delle competenze e dei talenti, non mi pare che sia il caso da parte degli scrittori di invocare una inserzione nell'ingranaggio della gran macchina produttiva ancora più diffusa e completa di quella attuale.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "E così bisogna servire, rendersi utili, collaborare [...].", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "L'unica cosa da pretendere sarà se mai un'altra: e cioè che il nostro servizio, la nostra collaborazione, non abbiano a risolversi in una alienazione della nostra natura e del nostro destino.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Vendere l'anima: ecco uno sbaglio che l'utente vero, il destinatario autentico e indispensabile, così poco adatto a far parte delle inerti assemblee consumistiche vagheggiate dalle fantasie dei tecnici e dei datori di lavoro, non perdona mai.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "La vita è musicale, si sa. Sui suoi temi fondamentali, sulle sue ''frasi'' più intense, non ama indugiare.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Come se non fosse evidente, viceversa, che la storia è fatta anche di cose minori, di episodi secondari, marginali, e che ogni monumento, per continuare a vivere, non può essere separato senza danno, spesso irreparabile, dall'ambiente circostante.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "È molto strano, me ne rendo conto, da parte mia, che sono socialista, vi venga questo invito alla conservazione.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Sennonché, oggi, in questa materia, credo non esista altra via per essere autenticamente, onestamente rivoluzionari.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "È tempo che il proletariato assuma la piena responsabilità storica del proprio potere, è tempo che il proletariato ferrarese sappia conservare ciò che gli è stato tramandato dagli avi aristocratici e borghesi.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Certo, che sono di origine borghese. Però, siccome non sono un borghese decadente, ed ho il senso delle mie responsabilità, proprio per questo milito in un partito di sinistra.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Fra due o trecento anni, quando la lingua italiana sarà diventata veramente nazionale, e non sarà più indispensabile far studiare ai ragazzi delle scuole il latino, il quale resta a tutt'oggi l'unico connettivo del caos linguistico nazionale, allora, anche in Italia, tutto sarà possibile.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Per ciò che mi riguarda, non ho ambizioni letterarie di tipo balzachiano. Non mi importa niente di dare un quadro generale della nostra società.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Vorrei poter scrivere qualcosa che si avvicinasse al lirismo e alla tensione narrativa dei ''Malavoglia'', di ''Senilità'', e, soprattutto, di ''The Scarlet Letter'' di Hawthorne: libro che non posso rileggere senza provare, ogni volta, la più violenta commozione.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Chi corre dietro al pubblico, vuol dire che dentro di sé non ha niente.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "E pur respingendo le aberrazioni deliranti di certa medicina «industriale», o meglio fantascientifica, badiamo piuttosto, specialmente noi letterati, a debellare quella che fra le malattie contemporanee è la più diffusa nell'ambito della categoria: l'estetismo, il culto narcisistico del proprio io spirituale, insaziato di privilegi ottenuti a scapito di chi, come patrimonio personale, non può disporre che del proprio corpo, a scapito dei più...", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Benché il gioco della torre sia ''sempre'' iniquo, specie poi se proposto a un moribondo, sono d'accordo: la vivisezione è un orrore, bisogna opporvisi.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Ma non basta, bisogna andare più in là. Anche i macelli sono un orrore.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Anche le immense stragi di animali di tutti i tipi che gli uomini perpetrano giorno dopo giorno per nutrirsi, anche esse, oggi, non appaiono meno infami.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "La civiltà industriale e tecnologica ha permesso all'umanità di sconfiggere o quasi la morte precoce. Nel corso degli ultimi cento anni la popolazione terrestre ha potuto triplicarsi. E tuttavia gli uomini continuano oggi ancora a nutrirsi come una volta, come sempre, di carne sanguinante, oggi ancora continuano a fondare la loro sussistenza sulla morte di altri esseri viventi.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "La verità è che la civiltà industriale e tecnologica non va rifiutata, bensì corretta, piegata, dominata.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Capace, come è, di fornire surrogati di tutto, o quasi tutto, perché non le chiediamo di riscattarci dall'abbiezione della più grossa delle nostre contraddizioni, l'organizzato assassinio degli animali?", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Per ciò che riguarda esclusivamente me, gli anni dal '37 al '43, che dedicai quasi del tutto all'attività antifascista clandestina (non ripresi a scrivere che nel '42, quando nell'estate di quell'anno buttai giù le poesie che più tardi avrei pubblicato nel volumetto ''Storie dei poveri amanti'', del '45), furono tra i più belli e più intensi dell'intera mia esistenza.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Mi salvarono dalla disperazione a cui andarono incontro tanti ebrei italiani, mio padre compreso, col conforto che mi dettero d'essere totalmente dalla parte della giustizia e della verità, e persuadendomi soprattutto a non emigrare.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Senza quegli anni per me fondamentali, credo che non sarei mai diventato uno scrittore.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Sì. Proprio il consistere del minimo, del pressoché inesistente, accanto al sublime, mi fa sperare d'avere scritto dei libri che, in qualche modo, abbiano a che fare con la vita, con la vita nella sua realtà, e quindi con la poesia.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Siamo dilettanti in tutto, ma non nel campo della vita morale.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "In questo campo sentiamo di non essere inferiori a nessuno, rivendichiamo la nostra competenza. Qui siamo altamente competenti.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "È necessario che ci si convinca – anche in termini meramente capitalistici, magari – che vale la pena di espandersi e di consumare un po' meno, perché l'uomo resti uomo.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Noi amiamo l'arte, ma riteniamo che essa non vada sottratta al contesto sociale in cui si è manifestata.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Crediamo non abbia senso restaurare e conservare un centro storico, trasformandolo da agglomerato naturale di vita collettiva in residenza di lusso per esteti e maniaci dell'antico.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "E dunque: perché ci si gingilla, tuttora, con l'invio sul posto di comitati o comitatoni ministeriali?", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Non sartà soltanto perché passi dell'altro tempo, giusto il tempo necessario perché anche i bambini si rassegnino all'idea di una Venezia chiusa da ogni parte dentro un anello di superbe dighe cementizie, più o meno olandesi o longaroniane: di una Venezia in bagnarola?", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "La natura e la storia, in Italia, sono così tanto apparentate fra di loro che sarebbe impossibile separarle.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Il territorio nella sua configurazione naturale è praticamente inesistente; nel tempo, in tutto il paese, la natura è stata rimodellata o quanto meno segnata dal lavoro dell'uomo.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Questa fusione della natura e dell'intervento umano è evidente in tutta la sua bellezza, varietà e coerenza; ma il miracolo di questo equilibrio si è manifestato come tale solo al momento in cui è iniziata la sua distruzione – prima sporadica e poi sistematica.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Lo ripeto: Venezia soffre soprattutto delle conseguenze di una cultura che tende ad estrapolarla, a farne qualcosa che non appartiene più alla vita, ma soltanto ai sogni dei poeti (dei cattivi poeti, tuttavia, giacché i poeti veri hanno, e come!, il senso del rapporto tra l'arte e la vita).", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Ma torniamo a ciò che fin dall'inizio siamo stati. Politici senza esserlo, non è che fossimo contro la civiltà tecnologico-industriale nel cui ambito ormai stavamo e, in qualche modo, eravamo soddisfatti di stare.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Volevamo tuttavia che essa, la civiltà tecnologico-industriale, si desse una religione.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Non siamo come i Verdi, noi. Ci guardiamo bene dal sognare che l'Italia e il mondo tornino indietro, verso la civiltà agricolo-forestale da cui tutti proveniamo.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Vogliamo però che la civiltà tecnologico-industriale, di cui facciamo parte, la smetta di tentare di convincere il mondo che è opportuno l'avvento di un'epoca di consumatori-consumati.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Noi siamo diversi, vogliamo che gli uomini continuino a essere uomini.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Perché la poesia non è il fiore sul vulcano. Brama il contesto, esige le strutture.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "È il riflesso della vita, la ''prova'' della vita. E, proprio come la vita, non è ''mai'' pura.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Invece che perder tempo a postulare impossibili ritorni ad arcadie pastorali, d'altronde abbondantemente intrise, a scrutarle da vicino, di sangue e di dolore, perché non la forziamo, la civiltà industriale e tecnologica, questo frutto supremo dell'intelletto umano, a darsi una religione? A darcela?", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Molto spesso, negli intellettuali di sinistra, affiora la preoccupazione di apparire dei perdigiorno innamorati del Bello.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Mentre, invece – come del reto Terranova medesimo ha ammesso –, il momento estetico è fondamentale.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Un parco naturale, signor presidente, è, prima che una forma di gestione del territorio a scopi conservatori, una grande occasione di turismo, di quello vero, di quello cioè che visita un parco rispettandone i valori e rinunciando a pretenderne il sacrificio con ragnatele di impianti e strade con costruzioni cementizie.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "L'Arte, lo sappiamo, è sempre uguale a sé stessa. Sta là, diversa dalla Vita, anzi il suo contrario, a ricordarci della Vita, e, talvolta, addirittura a restituircela.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Il fatto è che noi, figli dello storicismo, noi invece siamo cambiati. Cambiati per sempre.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "L'America mi interessa perché è la sede, il punto di parenza della civiltà industriale nella quale siamo tutti coinvolti. Le origini sono qui.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Ora, la cosa la stupirà, ma sento che qui c'è qualcosa d'altro: quialcosa di quella religione della società che fu il portato della rivoluzione protestante.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "È questo fondamento di religiosità che impedisce al consumismo materialistco di trasformare i suoi utenti in oggetti, in puri robots.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Per esempio, ammiro molto il senso della ''privacy'' che è qui, il culto della casa.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "E lo stesso modo di gestire il traffico.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Perché i popolani italiani uscissero dal loro ghetto, non c'è mai stato che un mezzo, imparare il latino per poi passare all'italiano nazional-popolare del Manzoni.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Era impensabile non passare attraverso il latino.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Oggi, qui in America, [per gli immigrati italiani bilingui] invece del latino c'è l'inglese.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Ma l'Italia – io lo ricordo sempre agli americani – è la matrice culturale del corso moderno.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Senza il ripensamento critico del passato avvenuto nel rinascimento, il mondo, che era antico, non sarebbe diventato moderno.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Il patrimonio artistico è la prova, la testimonianza puntuale, del processo spirituale che ha cambiato il profilo della civiltà.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "È per questo motivo che l'Italia, per me, ha un un carattere «sacro».", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Se mi occupo d'Italia Nostra è anche perché in contrasto con la mia natura contemplativa mi sono sempre interessato di politica.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Dopo la dittatura non si è verificato il trapasso alla democrazia, ma solo la spartizione fra i partiti del potere e dello spazio politico.", Author = "Giorgio Bassani" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giorgio_Bassani", Text = "Siccome lo Stato non c'è, gli intellettuali, a seconda delle loro inclinazioni ideologiche, si lasciano assorbire dai vari potentati.", Author = "Giorgio Bassani" },
        };
    }
}